 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    # Interior singleton colors are the ray sources; boundary runs are guides.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or counts[color] != 1:
                continue
            for cc in range(w):
                if grid[r][cc] == bg:
                    out[r][cc] = color
            for rr in range(h):
                if grid[rr][c] == bg:
                    out[rr][c] = color
            out[r][c] = 4
    return out
